import numpy as np
from scipy.optimize import minimize


def poisson_nll(beta, X, y, offset):
    eta = X @ beta + offset
    return np.sum(np.exp(eta) - y * eta)


def fit_poisson(X, y, offset):
    X = np.asarray(X, dtype=float)
    res = minimize(poisson_nll, np.zeros(X.shape[1]), args=(X, y, offset), method='BFGS', options={'gtol': 1e-8})
    return res.x
